				api  = grpc_gateway.NewServeMux(grpc_gateway.WithMarshalerOption(grpc_gateway.MIMEWildcard, &grpc_gateway.JSONPb{OrigName: false}))
				opts = []grpc.DialOption{grpc.WithInsecure()}
			)

			if cfg.Server.Protocol == HTTPS {
				creds, err := credentials.NewClientTLSFromFile(cfg.Server.CertFile, "")
				if err != nil {
					return errors.Wrap(err, "loading grpc client TLS credentials")
				}
				opts = []grpc.DialOption{grpc.WithTransportCredentials(creds)}
			}

			if err := pb.RegisterFliptHandlerFromEndpoint(ctx, api, fmt.Sprintf("%s:%d", cfg.Server.Host, cfg.Server.GRPCPort), opts); err != nil {
				return errors.Wrap(err, "connecting to grpc server")
			}

			if cfg.Cors.Enabled {
				cors := cors.New(cors.Options{
					AllowedOrigins:   cfg.Cors.AllowedOrigins,
					AllowedMethods:   []string{"GET", "POST", "PUT", "DELETE", "OPTIONS"},
					AllowedHeaders:   []string{"Accept", "Authorization", "Content-Type", "X-CSRF-Token"},
					ExposedHeaders:   []string{"Link"},
					AllowCredentials: true,
					MaxAge:           300,
				})

				r.Use(cors.Handler)
				logger.Debugf("CORS enabled with allowed origins: %v", cfg.Cors.AllowedOrigins)
			}

			r.Use(middleware.RequestID)
			r.Use(middleware.RealIP)
			r.Use(middleware.Compress(gzip.DefaultCompression))
			r.Use(middleware.Heartbeat("/health"))
			r.Use(middleware.Recoverer)
			r.Mount("/metrics", promhttp.Handler())
			r.Mount("/api/v1", api)
			r.Mount("/debug", middleware.Profiler())

			r.Route("/meta", func(r chi.Router) {
				r.Use(middleware.SetHeader("Content-Type", "application/json"))
				r.Handle("/info", info)
				r.Handle("/config", cfg)
			})

			if cfg.UI.Enabled {
				r.Mount("/docs", http.StripPrefix("/docs/", http.FileServer(swagger.Assets)))
				r.Mount("/", http.FileServer(ui.Assets))
			}

			httpServer = &http.Server{
				Addr:           fmt.Sprintf("%s:%d", cfg.Server.Host, httpPort),
				Handler:        r,
				ReadTimeout:    10 * time.Second,
				WriteTimeout:   10 * time.Second,
				MaxHeaderBytes: 1 << 20,
			}

			scheme := cfg.Server.Protocol.String()
			logger.Infof("api server running at: %s://%s:%d/api/v1", scheme, cfg.Server.Host, httpPort)

			if cfg.UI.Enabled {
				logger.Infof("ui available at: %s://%s:%d", scheme, cfg.Server.Host, httpPort)
			}

			var err error
			if cfg.Server.Protocol == HTTPS {
				err = httpServer.ListenAndServeTLS(cfg.Server.CertFile, cfg.Server.CertKey)
			} else {
				err = httpServer.ListenAndServe()
			}
			if err != http.ErrServerClosed {
				return err
			}

			return nil
		})
	}

	select {
	case <-interrupt:
		break
	case <-ctx.Done():
		break
	}

	logger.Info("shutting down...")

	cancel()

	shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer shutdownCancel()
	if httpServer != nil {
		_ = httpServer.Shutdown(shutdownCtx)
	}

	if grpcServer != nil {
		grpcServer.GracefulStop()
	}

	return g.Wait()
}
# Configuration

There are two ways to configure Flipt: using a configuration file or through environment variables.

## Configuration File

The default way that Flipt is configured is with the use of a configuration file `default.yml`.

This file is read when Flipt starts up and configures several important properties for the server.

You can edit any of these properties to your liking, and on restart Flipt will pick up the new changes.

!!! note
    These defaults are commented out in `default.yml` to give you an idea of what they are. To change them you'll first need to uncomment them.

These properties are as follows:

| Property | Description | Default |
|---|---|---|
| log.level | Level at which messages are logged (trace, debug, info, warn, error, fatal, panic) | info |
| ui.enabled | Enable UI and API docs | true |
| cors.enabled | Enable CORS support | false |
| cors.allowed_origins | Sets Access-Control-Allow-Origin header on server | "*" (all domains) |
| cache.memory.enabled | Enable in-memory caching | false |
| cache.memory.items | Number of items in-memory cache can hold | 500 |
| server.host | The host address on which to serve the Flipt application | 0.0.0.0 |
| server.protocol | Protocol for the REST API, UI, and gRPC endpoints (`http` or `https`) | http |
| server.http_port | The port on which to serve the Flipt REST API and UI over HTTP | 8080 |
| server.https_port | The port on which to serve the Flipt REST API and UI over HTTPS | 443 |
| server.grpc_port | The port on which to serve the Flipt GRPC server | 9000 |
| server.cert_file | TLS certificate file (required for HTTPS) | unset |
| server.cert_key | TLS private key file (required for HTTPS) | unset |
| db.url | URL to access Flipt database | file:/var/opt/flipt/flipt.db |
| db.migrations.path | Where the Flipt database migration files are kept | /etc/flipt/config/migrations |

To enable HTTPS for the REST API, UI, and gRPC endpoint, configure the protocol and certificate pair:

```yaml
server:
  protocol: https
  https_port: 443
  cert_file: /path/to/server.crt
  cert_key: /path/to/server.key
```

## Using Environment Variables

All options in the configuration file can be overridden using environment variables using the syntax:

```shell
FLIPT_<SectionName>_<KeyName>
```

!!! tip
    Using environment variables to override defaults is especially helpful when running with Docker as described in the [Installation](installation.md) documentation.

Everything should be upper case, `.` should be replaced by `_`. For example, given these configuration settings:

```yaml
server:
  grpc_port: 9000

db:
  url: file:/var/opt/flipt/flipt.db
```

You can override them using:

```shell
export FLIPT_SERVER_GRPC_PORT=9001
export FLIPT_DB_URL="postgres://postgres@localhost:5432/flipt?sslmode=disable"
```

